// =============================================================================
// catalogInfo — what the registry tables do not say about an object
// =============================================================================
//
// Per type and per variant: the words the Add menu and the AI choose by (description,
// tags), the display name, and the transform / material a variant starts with.
// Configs live in the registry's DEFAULT_* tables (effects, particles, grids, lights,
// environment, space); only mesh, gallery and text variants carry their config here,
// because those families have no defaults table.
//
// `key` is permanent (it is what scenes store in config.type / shapeType / layout).
// `legacyId` is the row id the DB catalog used, kept so templates (objectTypeId) and
// existing ?variantId= links keep resolving. New entries have none.
//
// Generated 2026-10-04 from the DB export (properties/typesAndVatiants.json); edit by hand from now on.

export interface CatalogTypeInfo {
    key: string; legacyId?: string; description: string; icon: string; order: number; enabled: boolean; defaultVariant?: string;
}
export interface CatalogVariantInfo {
    key: string; legacyId?: string; name: string; description: string; tags: string[];
    transform?: Record<string, unknown>; material?: Record<string, unknown>; config?: Record<string, unknown>;
}

